/* SPI1: route default, on every part */
#define CH32RV_SPI1_SCK PA5
#define CH32RV_SPI1_MISO PA6
#define CH32RV_SPI1_MOSI PA7
#define CH32RV_SPI1_CLKEN_ADDR 0x40021018u
#define CH32RV_SPI1_CLKEN_MASK 0x00001000u
#define CH32RV_SPI1_REMAP_MASK 0x00000001u
#define CH32RV_SPI1_REMAP_VAL  0x00000000u
/* SPI1 routes for setRoute()/setPins(): route number, then SCK, MISO, MOSI */
#define CH32RV_SPI1_ROUTE_COUNT 2
#define CH32RV_SPI1_ROUTES { \
    { 0, { PA5, PA6, PA7 }, 0x00000000u, 0x00000000u }, \
    { 1, { PB3, PB4, PB5 }, 0x00000001u, 0x00000000u }, \
}
/* SPI1's NSS pad on each route (setHwCs()): the route's value, SCK, MISO, MOSI, NSS. */
#define CH32RV_SPI1_NSS_PADS { \
    { 0x00000000u, { PA5, PA6, PA7, PA4 } }, \
    { 0x00000001u, { PB3, PB4, PB5, PA15 } }, \
}
/* SPI1's DMA requests (the SPI library's buffer transfers). */
#define CH32RV_SPI1_DMA_RX CH32RV_DMA_LINE(1, 2, 0x4002001cu, 0x40020000u, 4u, 0u)
#define CH32RV_SPI1_DMA_TX CH32RV_DMA_LINE(1, 3, 0x40020030u, 0x40020000u, 8u, 0u)
#define CH32RV_SPI1_DMA_RX_IRQ DMA1_Channel2
#define CH32RV_SPI1_DMA_TX_IRQ DMA1_Channel3
/* SPI2: route default, on 3 of 4 parts */
#define CH32RV_SPI2_SCK PB13
#define CH32RV_SPI2_MISO PB14
#define CH32RV_SPI2_MOSI PB15
#define CH32RV_SPI2_CLKEN_ADDR 0x4002101cu
#define CH32RV_SPI2_CLKEN_MASK 0x00004000u
#if defined(CH32RV_PART_CH32V103C6T6)
#define CH32RV_SPI2_ABSENT 1   /* not on this part */
#endif
/* SPI2's NSS pad on each route (setHwCs()): the route's value, SCK, MISO, MOSI, NSS. */
#define CH32RV_SPI2_NSS_PADS { \
    { 0x00000000u, { PB13, PB14, PB15, PB12 } }, \
}
/* SPI2's DMA requests (the SPI library's buffer transfers). */
#define CH32RV_SPI2_DMA_RX CH32RV_DMA_LINE(1, 4, 0x40020044u, 0x40020000u, 12u, 0u)
#define CH32RV_SPI2_DMA_TX CH32RV_DMA_LINE(1, 5, 0x40020058u, 0x40020000u, 16u, 0u)
#define CH32RV_SPI2_DMA_RX_IRQ DMA1_Channel4
#define CH32RV_SPI2_DMA_TX_IRQ DMA1_Channel5
/* Arduino's standard names for the first bus (SPI). These are
 * the pads of SPI1's default route above - a fact about
 * the chip, NOT a claim about how any board is wired. */
#if !defined(PIN_SPI_SCK) && defined(CH32RV_SPI1_SCK)
#define PIN_SPI_SCK CH32RV_SPI1_SCK
#define PIN_SPI_MISO CH32RV_SPI1_MISO
#define PIN_SPI_MOSI CH32RV_SPI1_MOSI
#define PIN_SPI_SS PA4
#endif
#if defined(PIN_SPI_SCK)
static const uint8_t SCK = PIN_SPI_SCK;
static const uint8_t MISO = PIN_SPI_MISO;
static const uint8_t MOSI = PIN_SPI_MOSI;
#endif
#if defined(PIN_SPI_SS)
static const uint8_t SS = PIN_SPI_SS;
#endif

/* ---- MCO, the clock output (device-data registers.csv: RCC CFGR0 MCO; pinout: RCC MCO) ---- */
#define CH32RV_MCO_PIN PA8
#define CH32RV_MCO_AF 0
#define CH32RV_MCO_SHIFT 24
#define CH32RV_MCO_MASK 0x07000000u
#define CH32RV_MCO_SYSCLK 4
